//! The reference dataset of `data/fixtures/dataset`, offline: its files
//! match `sha256.json`, it is valid under every profile with every object
//! verified, it conforms to the published schemas and exports nothing
//! identifying, and every `malformed/` case reports exactly its code.
//!
//! The reference is generated by `cytiq-engine`'s `dataset_fixtures` test;
//! `CYTIQ_BLESS=1` here only rewrites the lock.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use cytiq_population::dataset::{self, Profile, ReportStatus, ValidateOptions};
use cytiq_population::events;
use cytiq_population::issue::{IssueCode, Issues, Severity};
use cytiq_population::serialization::DocumentFormat;
use serde_json::{Value, json};

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../data/fixtures/dataset")
}

fn reference() -> PathBuf {
    fixtures().join("reference")
}

fn sha256(bytes: &[u8]) -> String {
    use sha2::Digest;
    use std::fmt::Write as _;
    sha2::Sha256::digest(bytes)
        .iter()
        .fold(String::new(), |mut text, byte| {
            write!(text, "{byte:02x}").unwrap();
            text
        })
}

fn inventory(directory: &Path, root: &Path, files: &mut BTreeMap<String, String>) {
    for entry in std::fs::read_dir(directory).unwrap() {
        let path = entry.unwrap().path();
        if path.is_dir() {
            inventory(&path, root, files);
            continue;
        }
        let relative = path
            .strip_prefix(root)
            .unwrap()
            .components()
            .map(|c| c.as_os_str().to_str().unwrap())
            .collect::<Vec<_>>()
            .join("/");
        if relative != "README.md" && relative != "sha256.json" {
            files.insert(relative, sha256(&std::fs::read(&path).unwrap()));
        }
    }
}

#[test]
fn fixture_files_match_their_lock() {
    let mut files = BTreeMap::new();
    inventory(&fixtures(), &fixtures(), &mut files);
    let actual = json!({"schema_version": 1, "files": files});
    let lock = fixtures().join("sha256.json");
    if std::env::var_os("CYTIQ_BLESS").is_some() {
        std::fs::write(&lock, serde_json::to_string_pretty(&actual).unwrap() + "\n").unwrap();
        return;
    }
    let pinned: Value = serde_json::from_slice(&std::fs::read(&lock).unwrap()).unwrap();
    assert_eq!(
        pinned, actual,
        "data/fixtures/dataset changed; regenerate and review it"
    );
}

#[test]
fn the_reference_dataset_is_valid_under_every_profile() {
    for profile in [Profile::Structural, Profile::MiflowcytMinimal] {
        let options = ValidateOptions {
            profile,
            root: None,
            verify_objects: true,
        };
        let report = dataset::validate(&reference().join("manifest.json"), &options).unwrap();
        assert_eq!(report.status, ReportStatus::Valid, "{:#?}", report.issues);
        // Panel B was compensated by other software: its definition is unknown.
        let warnings: Vec<_> = report
            .issues
            .iter()
            .filter(|issue| issue.severity == Severity::Warning)
            .map(|issue| (issue.code, issue.pointer.as_str()))
            .collect();
        assert_eq!(
            warnings,
            [(IssueCode::MissingMetadata, "/artifacts/4/layer/steps/0")]
        );
    }
}

fn manifest_value() -> Value {
    serde_json::from_slice(&std::fs::read(reference().join("manifest.json")).unwrap()).unwrap()
}

#[test]
fn the_reference_conforms_and_exports_nothing_identifying() {
    let manifest = manifest_value();
    dataset::conforms(&manifest, "dataset-manifest.schema.json").unwrap();
    for artifact in manifest["artifacts"].as_array().unwrap() {
        if artifact["contract"] != "cytiq.events.v1" {
            continue;
        }
        let path = reference().join(artifact["location"].as_str().unwrap());
        let summary = events::verify_file(&path, "", &mut Issues::new()).unwrap();
        let descriptor = serde_json::to_value(&summary.descriptor).unwrap();
        dataset::conforms(&descriptor, "events-layer.schema.json").unwrap();
    }
    // Denied TEXT of Case12 (Kaluza export) and Case30 (flowCore re-export)
    // never leaks: file names, dates, comment, last modifier, sample ids,
    // GUID, and no local path. `$CYT` (`Kaluza`) is allowlisted.
    for entry in walk(&reference()) {
        let bytes = std::fs::read(&entry).unwrap();
        for needle in [
            "Case12_P",
            "Case30_P",
            "exported using Kaluza",
            "Kaluza Cytobank",
            "04-Dec-15",
            "11:47:17",
            "@SAMPLEID",
            "FILENAME",
            "GUID",
            "$FIL",
            "$DATE",
            "$COM",
            "$LAST_MODIFIER",
            "$OriginalInstrument",
            "/Users/",
            "/home/",
            "/tmp/",
        ] {
            assert!(
                !bytes.windows(needle.len()).any(|w| w == needle.as_bytes()),
                "`{needle}` in {}",
                entry.display()
            );
        }
    }
}

fn walk(directory: &Path) -> Vec<PathBuf> {
    let mut files = Vec::new();
    for entry in std::fs::read_dir(directory).unwrap() {
        let path = entry.unwrap().path();
        if path.is_dir() {
            files.extend(walk(&path));
        } else {
            files.push(path);
        }
    }
    files
}

fn unescape(segment: &str) -> String {
    segment.replace("~1", "/").replace("~0", "~")
}

/// The parent of `pointer` and its last segment.
fn parent<'a>(document: &'a mut Value, pointer: &str) -> (&'a mut Value, String) {
    let (head, last) = pointer.rsplit_once('/').expect("pointer");
    let parent = document
        .pointer_mut(head)
        .unwrap_or_else(|| panic!("no parent for {pointer}"));
    (parent, unescape(last))
}

fn add(document: &mut Value, pointer: &str, value: Value) {
    let (parent, key) = parent(document, pointer);
    match parent {
        Value::Array(items) if key == "-" => items.push(value),
        Value::Array(items) => items.insert(key.parse().unwrap(), value),
        Value::Object(map) => {
            map.insert(key, value);
        }
        _ => panic!("cannot add at {pointer}"),
    }
}

/// A minimal RFC 6902 subset: add, replace, remove and copy.
fn apply(document: &mut Value, operations: &[Value]) {
    for step in operations {
        let path = step["path"].as_str().unwrap();
        match step["op"].as_str().unwrap() {
            "add" => add(document, path, step["value"].clone()),
            "replace" => {
                *document
                    .pointer_mut(path)
                    .unwrap_or_else(|| panic!("no {path}")) = step["value"].clone();
            }
            "remove" => {
                let (parent, key) = parent(document, path);
                match parent {
                    Value::Array(items) => {
                        items.remove(key.parse().unwrap());
                    }
                    Value::Object(map) => {
                        map.remove(&key).unwrap_or_else(|| panic!("no {path}"));
                    }
                    _ => panic!("cannot remove {path}"),
                }
            }
            "copy" => {
                let from = step["from"].as_str().unwrap();
                let value = document
                    .pointer(from)
                    .unwrap_or_else(|| panic!("no {from}"))
                    .clone();
                if document.pointer(path).is_some() && !path.ends_with("/-") {
                    let (parent, _) = parent(document, path);
                    if parent.is_array() {
                        add(document, path, value);
                    } else {
                        *document.pointer_mut(path).unwrap() = value;
                    }
                } else {
                    add(document, path, value);
                }
            }
            other => panic!("unsupported patch op {other}"),
        }
    }
}

#[test]
fn every_malformed_case_reports_its_code() {
    let mut cases = walk(&fixtures().join("malformed"));
    cases.sort();
    let mut covered = std::collections::BTreeSet::new();
    for case_path in cases {
        let case: Value = serde_json::from_slice(&std::fs::read(&case_path).unwrap()).unwrap();
        let expect: IssueCode = serde_json::from_value(case["expect"].clone()).unwrap();
        let profile = match case["profile"].as_str() {
            Some(name) => name.parse::<Profile>().unwrap(),
            None => Profile::Structural,
        };
        let mut document = manifest_value();
        apply(&mut document, case["patch"].as_array().unwrap());
        // The case is about its patch, not about the identity it changes.
        document.as_object_mut().unwrap().remove("dataset_id");
        let mut issues = Issues::new();
        let text = serde_json::to_vec(&document).unwrap();
        if let Some(manifest) = dataset::parse(&text, DocumentFormat::Json, &mut issues) {
            dataset::validate_document(&manifest, profile, &mut issues);
            if case["tier"] == "objects" {
                dataset::verify_objects(&manifest, &reference(), &mut issues);
            }
        }
        let name = case_path.file_name().unwrap().to_string_lossy();
        assert!(
            issues.codes(Severity::Error).contains(&expect),
            "{name}: expected {expect:?}, got {:#?}",
            issues.items()
        );
        if case["tier"] == "objects" {
            let mut document_only = Issues::new();
            let manifest = dataset::parse(&text, DocumentFormat::Json, &mut document_only).unwrap();
            dataset::validate_document(&manifest, profile, &mut document_only);
            assert!(
                !document_only.codes(Severity::Error).contains(&expect),
                "{name}: only object verification should find {expect:?}"
            );
        }
        covered.insert(expect);
    }
    let every_code = [
        IssueCode::UnsupportedSchema,
        IssueCode::MalformedDocument,
        IssueCode::MissingMetadata,
        IssueCode::PanelMismatch,
        IssueCode::IncompatibleSignalState,
        IssueCode::DuplicateEventIdentity,
        IssueCode::DuplicateAcquisition,
        IssueCode::DuplicateIdentifier,
        IssueCode::InvalidReference,
        IssueCode::InconsistentChannelOrder,
        IssueCode::MissingObject,
        IssueCode::CorruptArtifactHash,
        IssueCode::PrivacyViolation,
    ];
    assert_eq!(
        covered,
        every_code.into(),
        "every issue code has a malformed case"
    );
}
